import java.util.concurrent.*;
public final class MainActivity extends Activity {
 private final Handler ui=new Handler(Looper.getMainLooper());private final ScheduledExecutorService network=Executors.newSingleThreadScheduledExecutor();
 private String updatePrompted="";private boolean permissionRequested=false;private AppUpdates updates;private LocalStore store;private WarehouseApi api;private SyncEngine sync;private LinearLayout root,content;private TextView status,title,last,count;private EditText scanner;private Button undo,cancel,issue;private String documentId="",kind="",connection="Подключение…";private boolean resumed=false,clearing=false,busy=false,ready=false;private Runnable flush;private String lastCode="",lastSource="";private long lastScanAt=0;
 private final BroadcastReceiver scanReceiver=new BroadcastReceiver(){public void onReceive(Context context,Intent intent){if(resumed&&"android.intent.action.SCANRESULT".equals(intent.getAction())){String code=intent.getStringExtra("value");if(code!=null&&!code.trim().isEmpty())receive(code.trim(),"broadcast");}}};
 private static final int BG=Color.rgb(11,18,30),PANEL=Color.rgb(23,39,60),CYAN=Color.rgb(41,218,224),TEXT=Color.rgb(237,245,255);
 @Override public void onCreate(Bundle b){super.onCreate(b);store=new LocalStore(this);store.put("active_document","");api=new WarehouseApi(new SecurePrefs(this));sync=new SyncEngine(store,api);updates=new AppUpdates(this,store);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);screen();UpdateJob.schedule(this,true);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},7302);start();network.scheduleWithFixedDelay(()->{if(!resumed)return;if(ready)try{sync.sync();sync.catalog(false);connection="Связь с сервером есть";}catch(Exception e){connection=explain(e);}try{String update=updates.check(false);if(!update.isEmpty())connection=update;}catch(Exception updateError){store.put("update_check_error",updateError.getMessage()==null?"network_error":updateError.getMessage());connection="Ошибка обновления: "+updateError.getMessage();}DeviceStatus.send(this,store,api);ui.post(()->{refresh();offerUpdate();});},2,2,TimeUnit.SECONDS);}
 private String explain(Exception e){if(e instanceof WarehouseApi.ApiError){int code=((WarehouseApi.ApiError)e).status;if(code==401)return "Нужен повторный вход · сканы сохранены";if(code==403)return "Доступ отключён · сканы сохранены";return e.getMessage();}return "Нет связи · сканы сохранены на ТСД";}
 private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 private GradientDrawable panel(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(12));return d;}
 private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextColor(TEXT);t.setTextSize(size);t.setPadding(0,dp(6),0,dp(6));return t;}
 private Button button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextColor(TEXT);b.setTextSize(19);b.setBackground(panel(Color.rgb(0,112,221)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(62));p.setMargins(0,dp(8),0,0);b.setLayoutParams(p);b.setOnClickListener(v->action.run());return b;}
 private void screen(){root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(16),dp(10),dp(16),dp(12));root.setBackgroundColor(BG);if(Build.VERSION.SDK_INT>=35)root.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars());v.setPadding(dp(16)+bars.left,dp(10)+bars.top,dp(16)+bars.right,dp(12)+bars.bottom);return insets;});setContentView(root);status=text(connection,12);root.addView(status);content=new LinearLayout(this);content.setOrientation(1);root.addView(content,new LinearLayout.LayoutParams(-1,0,1));}
 private void task(Work work,Runnable done){if(busy)return;busy=true;status.setText("Подключаем…");network.execute(()->{try{work.run();ui.post(()->{busy=false;done.run();});}catch(Exception e){ui.post(()->{busy=false;if(e instanceof WarehouseApi.ApiError&&((WarehouseApi.ApiError)e).status==401){ready=false;login();}status.setText(e.getMessage());});}});}
 interface Work{void run()throws Exception;}
 private void start(){task(()->{if(api.auth()==null)return;if(api.device()!=null){try{api.call("info",new JSONObject());sync.catalog(true);ready=true;}catch(Exception e){if(!store.get("catalog_at").isEmpty()&&!(e instanceof WarehouseApi.ApiError&&(((WarehouseApi.ApiError)e).status==401||((WarehouseApi.ApiError)e).status==403))){ready=true;connection=explain(e);}else throw e;}}},()->{try{if(api.auth()==null)login();else if(api.device()==null)chooseStation();else home();}catch(Exception e){status.setText(e.getMessage());login();}});}
 private void login(){documentId="";kind="";content.removeAllViews();content.addView(text("Вход в FastGo",27));EditText email=new EditText(this),password=new EditText(this);email.setHint("Почта сотрудника");email.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);password.setHint("Пароль");password.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);email.setTextColor(TEXT);email.setHintTextColor(Color.LTGRAY);password.setTextColor(TEXT);password.setHintTextColor(Color.LTGRAY);content.addView(email);content.addView(password);content.addView(button("Войти",()->{String e=email.getText().toString().trim(),p=password.getText().toString();task(()->api.login(e,p),()->{password.setText("");hideKeyboard();start();});}));}
 private void chooseStation(){documentId="";content.removeAllViews();content.addView(text("Куда передавать сканы",24));status.setText("Ищем складской ноутбук…");network.execute(()->{try{JSONArray stations=(JSONArray)api.call("stations",new JSONObject());if(stations.length()==1){api.connect(stations.getJSONObject(0).getString("id"));sync.catalog(true);ready=true;ui.post(this::home);return;}ui.post(()->{status.setText(stations.length()==0?"Сначала откройте FastGo Склад на ноутбуке":"Выберите ноутбук один раз");for(int i=0;i<stations.length();i++)try{JSONObject s=stations.getJSONObject(i);content.addView(button(s.getString("name"),()->task(()->{api.connect(s.getString("id"));sync.catalog(true);ready=true;},this::home)));}catch(JSONException ignored){}});}catch(Exception e){ui.post(()->status.setText(e.getMessage()));}});}
 private void home(){store.put("active_document","");documentId="";kind="";scanner=null;hideKeyboard();content.removeAllViews();content.addView(text("Складской терминал",25));content.addView(button("Приход",()->open("receipt")));content.addView(button("Продажа",()->open("sale")));content.addView(button("Оплата ремонта",()->open("repair")));content.addView(button("Выдача запчастей",()->open("parts")));LinearLayout secondary=new LinearLayout(this);Button update=button("Обновить сейчас",()->task(()->{sync.catalog(true);sync.sync();connection=updates.check(true);},()->{refresh();updatePrompted="";permissionRequested=false;offerUpdate();}));Button catalog=button("Сверить каталог",()->task(()->{sync.catalog(true);sync.sync();connection="Каталог и очередь синхронизированы";},this::refresh));for(Button b:new Button[]{update,catalog}){b.setTextSize(13);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(48),1);lp.setMargins(0,dp(12),dp(4),0);secondary.addView(b,lp);}content.addView(secondary);String installed="";try{installed=getPackageManager().getPackageInfo(getPackageName(),0).versionName;}catch(Exception ignored){}TextView version=text("Нативное приложение · "+installed,12);content.addView(version);refresh();}
 private void open(String value){try{kind=value;JSONObject doc=store.open(kind);documentId=doc.getString("id");store.put("active_document",documentId);content.removeAllViews();LinearLayout heading=new LinearLayout(this);Button back=button("←",this::leaveDocument);heading.addView(back,new LinearLayout.LayoutParams(dp(54),dp(48)));title=text(kind.equals("receipt")?"Приход":kind.equals("sale")?"Продажа":kind.equals("parts")?"Выдача запчастей":"Оплата ремонта",25);heading.addView(title,new LinearLayout.LayoutParams(0,-2,1));content.addView(heading);
  last=text("Ожидаем сканирование",25);last.setTypeface(null,Typeface.BOLD);last.setGravity(Gravity.CENTER);last.setPadding(dp(10),dp(20),dp(10),dp(20));last.setBackground(panel(PANEL));ScrollView summary=new ScrollView(this);summary.addView(last,new android.widget.FrameLayout.LayoutParams(-1,-2));content.addView(summary,new LinearLayout.LayoutParams(-1,0,1));count=text("",14);content.addView(count);issue=button("Выдать",this::issueParts);issue.setVisibility(View.GONE);content.addView(issue);undo=button("Отменить последний скан",this::undo);content.addView(undo);cancel=button(kind.equals("receipt")?"Отменить приход":kind.equals("repair")?"Отменить оплату ремонта":kind.equals("parts")?"Отменить выдачу":"Отменить продажу",this::cancelDocument);cancel.setContentDescription("Отменить сканирование документа");cancel.setBackground(panel(Color.rgb(168,45,60)));cancel.setTextSize(17);cancel.setPadding(dp(8),0,dp(8),0);if(Build.VERSION.SDK_INT>=26)cancel.setAutoSizeTextTypeUniformWithConfiguration(12,17,1,android.util.TypedValue.COMPLEX_UNIT_SP);content.addView(cancel);
  scanner=new EditText(this);scanner.setSingleLine(true);scanner.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);scanner.setShowSoftInputOnFocus(false);scanner.setImeOptions(EditorInfo.IME_FLAG_NO_EXTRACT_UI|EditorInfo.IME_ACTION_DONE);scanner.setTextColor(BG);scanner.setBackgroundColor(BG);scanner.setCursorVisible(false);scanner.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);content.addView(scanner,new LinearLayout.LayoutParams(1,1));
  scanner.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int c){if(clearing)return;if(flush!=null)ui.removeCallbacks(flush);flush=()->flushScanner();ui.postDelayed(flush,180);}public void afterTextChanged(Editable e){}});
  scanner.setOnEditorActionListener((v,a,event)->{flushScanner();return true;});scanner.setOnKeyListener((v,code,event)->{if((code==KeyEvent.KEYCODE_ENTER||code==KeyEvent.KEYCODE_TAB)&&event.getAction()==KeyEvent.ACTION_DOWN){flushScanner();return true;}return false;});last.setOnClickListener(v->focusScanner());refresh();focusScanner();
 }catch(Exception e){status.setText(e.getMessage());}}
 private void flushScanner(){if(scanner==null||documentId.isEmpty())return;if(flush!=null)ui.removeCallbacks(flush);String code=scanner.getText().toString().trim();clearing=true;scanner.setText("");clearing=false;if(!code.isEmpty())receive(code,"editor");}
 private void receive(String code,String source){long now=android.os.SystemClock.elapsedRealtime();if(code.equals(lastCode)&&!source.equals(lastSource)&&now-lastScanAt<180)return;lastCode=code;lastSource=source;lastScanAt=now;scan(code);}
 private void scan(String code){if(documentId.isEmpty()||busy)return;try{JSONObject doc=store.doc(documentId);if(doc.optBoolean("cancel_requested")){status.setText("Отмена ожидает подтверждения сервера");return;}if(doc.optBoolean("issue_requested")){status.setText("Выдача отправлена · ожидаем подтверждения сервера");return;}if(kind.equals("parts")){
  if(code.startsWith("FGPARTS1.")){
   if(ScanDocument.items(doc).length()==0)throw new IllegalStateException("Сначала отсканируйте запчасти");
   final String target=documentId;task(()->{JSONObject quote=(JSONObject)api.call("parts_pickup_quote",new JSONObject().put("code",code));JSONObject current=store.doc(target);if(current==null||!current.optString("state").equals("open")||current.optBoolean("cancel_requested"))return;current.put("pickup_code",code).put("pickup",quote);store.save(current);},this::refresh);return;
  }
  if(store.match(code)==null)throw new IllegalStateException("Запчасть не найдена. Сверьте каталог и сканируйте её штрихкод.");
  doc.remove("pickup_code");doc.remove("pickup");store.save(doc);
 }if(kind.equals("sale")&&ScanDocument.isRepairCode(code)){if(ScanDocument.count(doc)>0)throw new IllegalStateException("Завершите или отмените продажу перед QR ремонта");open("repair");doc=store.doc(documentId);}if(kind.equals("repair")&&ScanDocument.count(doc)>0){status.setText("Дождитесь оплаты ремонта на ноутбуке");return;}store.scan(documentId,code);refresh();status.setText("Код принят · сохранён на ТСД");network.execute(()->{try{sync.sync();connection="Сервер подтвердил получение сканов";}catch(Exception e){connection=explain(e);}ui.post(this::refresh);});}catch(Exception e){status.setText(e.getMessage());}focusScanner();}
 private void issueParts(){if(!kind.equals("parts")||documentId.isEmpty()||busy)return;try{JSONObject doc=store.doc(documentId);if(!doc.has("pickup")||ScanDocument.items(doc).length()==0)throw new IllegalStateException("Сначала отсканируйте детали и QR мастера");doc.put("issue_requested",true);store.save(doc);refresh();task(()->sync.sync(),this::refresh);}catch(Exception e){status.setText(e.getMessage());}}
 private void offerUpdate(){if(!resumed||busy||!documentId.isEmpty()||!updates.ready()||!updates.canInstall()||updatePrompted.equals(updates.readyVersion()))return;try{if(((KeyguardManager)getSystemService(KEYGUARD_SERVICE)).isKeyguardLocked())return;if(!updates.installerAllowed()&&permissionRequested)return;permissionRequested=true;if(updates.install())updatePrompted=updates.readyVersion();else{connection="Разрешите FastGo устанавливать обновления APK, затем вернитесь в приложение";refresh();}}catch(Exception e){connection=e.getMessage();refresh();}}
 private void cancelDocument(){if(documentId.isEmpty()||busy)return;final String id=documentId;try{if(store.doc(id).optBoolean("issue_requested")){status.setText("Выдача уже отправлена. Ожидаем подтверждения сервера.");return;}}catch(Exception e){status.setText(e.getMessage());return;}new AlertDialog.Builder(this).setTitle(kind.equals("repair")?"Отменить выбранный ремонт?":"Отменить документ?").setMessage(kind.equals("parts")?"Отменить набор деталей? Складские остатки не изменятся.":"Сканы будут убраны из очереди ноутбука. Проведённая оплата при этом не возвращается.").setPositiveButton("Да, отменить",(d,w)->{try{store.requestCancel(id);refresh();task(()->sync.sync(),this::refresh);}catch(Exception e){status.setText(e.getMessage());}}).setNegativeButton("Продолжить",(d,w)->focusScanner()).show();}
 private void undo(){try{if(store.doc(documentId).optBoolean("issue_requested")){status.setText("Выдача уже отправлена");return;}if(kind.equals("parts")){JSONObject d=store.doc(documentId);d.remove("pickup_code");d.remove("pickup");store.save(d);}if(kind.equals("repair")){cancelDocument();return;}if("processing".equals(store.get("server:"+documentId))){status.setText("Документ проводится на ноутбуке");return;}store.undo(documentId);refresh();}catch(Exception e){status.setText(e.getMessage());}focusScanner();}
 private void refresh(){if(isFinishing())return;status.setText(connection);if(documentId.isEmpty())return;try{JSONObject doc=store.doc(documentId);if(doc==null)return;if(doc.optString("state").equals("done")){boolean cancelled="true".equals(store.get("cancelled:"+documentId));home();status.setText(cancelled?"Сканирование отменено":!store.get("issue_result:"+doc.getString("id")).isEmpty()?"Запчасти выданы и привязаны к ремонту":"Операция завершена на ноутбуке");return;}cancel.setEnabled(!busy&&!doc.optBoolean("issue_requested")&&!doc.optBoolean("cancel_requested")&&!"processing".equals(store.get("server:"+documentId)));if(doc.optBoolean("cancel_requested"))status.setText("Отмена сохранена · ожидаем подтверждения сервера");JSONObject event=ScanDocument.last(doc);issue.setVisibility(kind.equals("parts")&&doc.has("pickup")?View.VISIBLE:View.GONE);issue.setEnabled(!busy);if(kind.equals("parts")){JSONObject pickup=doc.optJSONObject("pickup");int total=ScanDocument.count(doc);StringBuilder details=new StringBuilder(pickup==null?"Буфер запчастей":"Ремонт № "+pickup.optString("number")+"\n"+pickup.optString("vehicle")+"\n"+pickup.optString("master_name"));JSONArray buffer=ScanDocument.items(doc);for(int i=0;i<buffer.length();i++){JSONObject item=buffer.getJSONObject(i),part=store.part(item.getString("part_id"));details.append("\n").append(part==null?item.getString("part_id"):part.optString("name")).append(" · ").append(item.getInt("quantity")).append(" шт.");}last.setText(total==0?"Сканируйте запчасти":details.toString());count.setText(doc.optBoolean("issue_requested")?"Выдача отправлена · повторяем до подтверждения сервера":total+" шт. · "+(pickup==null?"Затем сканируйте QR мастера":"Проверьте ремонт и нажмите «Выдать»"));}else if(kind.equals("repair")){String value=store.get("repair:"+documentId);last.setText(value.isEmpty()?(event==null?"Ожидаем QR ремонта":"QR сохранён · получаем сумму"):value);count.setText("Подтверждение оплаты — на ноутбуке");}
 else{last.setText(event==null?"Ожидаем сканирование":event.has("part_id")?event.optString("name")+"\n"+String.format(java.util.Locale.forLanguageTag("ru-RU"),"%.2f ₽",event.optDouble("price",0)):"Неизвестный код\n"+event.optString("code")+"\nСохранён для разбора на ноутбуке");int total=ScanDocument.count(doc);count.setText(total==0?"":total+" сканов · "+(doc.optInt("acked")>=doc.getInt("revision")?"Сервер подтвердил":"Ожидают отправки"));}undo.setVisibility(event==null||kind.equals("repair")?View.GONE:View.VISIBLE);undo.setEnabled(!doc.optBoolean("issue_requested")&&!"processing".equals(store.get("server:"+documentId)));}catch(Exception e){status.setText(e.getMessage());}}
 private void focusScanner(){if(resumed&&scanner!=null&&!documentId.isEmpty()){scanner.requestFocus();hideKeyboard();}}
 private void hideKeyboard(){View focus=getCurrentFocus();if(focus!=null)((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(focus.getWindowToken(),0);}
 @Override protected void onResume(){super.onResume();resumed=true;store.put("activity_resumed","true");IntentFilter filter=new IntentFilter("android.intent.action.SCANRESULT");if(Build.VERSION.SDK_INT>=33)registerReceiver(scanReceiver,filter,Context.RECEIVER_EXPORTED);else registerReceiver(scanReceiver,filter);ui.postDelayed(this::focusScanner,100);}
 @Override protected void onPause(){resumed=false;store.put("activity_resumed","false");try{unregisterReceiver(scanReceiver);}catch(IllegalArgumentException ignored){}if(flush!=null)ui.removeCallbacks(flush);flushScanner();super.onPause();}
 @Override public void onWindowFocusChanged(boolean has){super.onWindowFocusChanged(has);if(has)ui.post(this::focusScanner);}
 private void leaveDocument(){try{if(!documentId.isEmpty()){if((kind.equals("repair")||kind.equals("parts"))&&ScanDocument.count(store.doc(documentId))>0){cancelDocument();return;}if(ScanDocument.count(store.doc(documentId))==0){store.requestCancel(documentId);network.execute(()->{try{sync.sync();}catch(Exception e){connection=explain(e);}ui.post(this::refresh);});}}}catch(Exception e){status.setText(e.getMessage());return;}home();}
 @Override public void onBackPressed(){if(!documentId.isEmpty())leaveDocument();else super.onBackPressed();}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==7301){updatePrompted=updates.readyVersion();connection=result==RESULT_OK?"Обновление установлено":"Установка отложена · нажмите «Обновить сейчас» для повтора";refresh();}}
 @Override protected void onDestroy(){network.shutdown();ui.removeCallbacksAndMessages(null);super.onDestroy();}
}
